<?php
namespace App\Jobs;use App\Models\CommunicationDelivery;use App\Services\ChannelDeliveryService;use Illuminate\Bus\Queueable;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Bus\Dispatchable;use Illuminate\Queue\InteractsWithQueue;use Illuminate\Queue\SerializesModels;use Illuminate\Support\Facades\DB;
class SendCommunicationDelivery implements ShouldQueue{use Dispatchable,InteractsWithQueue,Queueable,SerializesModels;public int $tries=4;public array $backoff=[60,300,900];public function __construct(public int $deliveryId){}public function handle(ChannelDeliveryService $service):void{$d=CommunicationDelivery::with('campaign')->findOrFail($this->deliveryId);if(!in_array($d->status,['queued','retrying','failed']))return;$d->increment('attempts');try{$r=$service->send($d);$d->update(['status'=>$r['status'],'provider_message_id'=>$r['id'],'provider_response'=>$r['response'],'delivered_at'=>$r['status']==='delivered'?now():null,'failed_at'=>null]);$d->campaign()->increment('sent_count');$this->timeline($d,$r['status']);$this->finish($d);}catch(\Throwable $e){$d->update(['status'=>$this->attempts()<$this->tries?'retrying':'failed','provider_response'=>$e->getMessage(),'failed_at'=>now()]);if($this->attempts()>=$this->tries){$d->campaign()->increment('failed_count');$this->timeline($d,'failed');$this->finish($d);}throw $e;}}private function timeline(CommunicationDelivery $d,string $status):void{if($d->recipient_type!=='guardian')return;DB::table('guardian_communication_events')->insert(['guardian_id'=>$d->recipient_id,'student_id'=>null,'channel'=>$d->channel,'direction'=>'outbound','subject'=>$d->campaign->subject?:$d->campaign->name,'content'=>$d->campaign->body,'status'=>$status,'meta'=>json_encode(['delivery_id'=>$d->id]),'created_at'=>now(),'updated_at'=>now()]);}private function finish(CommunicationDelivery $d):void{$c=$d->campaign->fresh();if(!$c->deliveries()->whereIn('status',['queued','retrying'])->exists())$c->update(['status'=>'completed','completed_at'=>now()]);}}
